const items = $input.all();
const ZONE_LABELS = { ZONA_A: 'Orquideario', ZONA_B: 'Jardín', ZONA_C: 'Terraza', ZONA_D: 'Ventanas', EXTERIOR: 'Exterior' };
const results = [];

for (const item of items) {
  const row = item.json;
  if (!row.notif_id) continue;

  let zonesStr = 'General';
  if (row.zones) {
    let arr = Array.isArray(row.zones) ? row.zones : [row.zones];
    if (typeof row.zones === 'string' && row.zones.startsWith('{')) {
      arr = row.zones.replace(/[{}]/g, '').split(',');
    }
    zonesStr = arr.map(z => ZONE_LABELS[z.trim()] || z.trim()).join(', ');
  }

  const dateObj = new Date(row.scheduledAt);
  const timeStr = dateObj.toLocaleTimeString('es-VE', { hour: '2-digit', minute: '2-digit', hour12: true, timeZone: 'America/Caracas' });

  const replyText = `\u200B\n⚠️ *Confirmación de Tanque de Agroquímicos*\n\n` +
    `*Rutina*: ${row.schedule_name || 'Riego Agroquímico'}\n` +
    (row.agrochemical_name ? `*Producto*: ${row.agrochemical_name}\n` : '') +
    (row.preparation ? `*Receta*: ${row.preparation}\n` : '') +
    `*Zonas*: ${zonesStr}\n` +
    `*Hora Programada*: ${timeStr}\n\n` +
    `¿El tanque de mezcla se encuentra preparado para la ejecución automática?`;

  const keyboard = {
    inline_keyboard: [
      [{ text: '✅ Confirmar Tanque', callback_data: `agro_hw_confirm:${row.taskId}:${row.notif_id}` }],
      [
        { text: '⏱️ Posponer 24h', callback_data: `agro_hw_postpone:${row.taskId}:24:${row.notif_id}` },
        { text: '⏱️ Posponer 48h', callback_data: `agro_hw_postpone:${row.taskId}:48:${row.notif_id}` }
      ],
      [{ text: '❌ Cancelar', callback_data: `agro_hw_cancel:${row.taskId}:${row.notif_id}` }]
    ]
  };

  results.push({ json: { taskId: row.taskId, notifId: row.notif_id, replyText, keyboard } });
}

return results;
